[Fact]
public void AC1_FormatterForReferencedAssemblyTypeRoundTrips()
{
    string projectB = """
        using MessagePack;
        using MessagePack.Formatters;
        using MessagePack.Resolvers;

        namespace ProjectB
        {
            [GeneratedMessagePackFormatter]
            public partial class MyTypeFormatter : IMessagePackFormatter<ProjectA.MyType> { }

            public static class Probe
            {
                public static string Run()
                {
                    var opts = MessagePackSerializerOptions.Standard.WithResolver(
                        CompositeResolver.Create(new IMessagePackFormatter[] { new MyTypeFormatter() }, new IFormatterResolver[] { StandardResolver.Instance }));
                    var bytes = MessagePackSerializer.Serialize(new ProjectA.MyType { Age = 42, Name = "Ann" }, opts);
                    var back = MessagePackSerializer.Deserialize<ProjectA.MyType>(bytes, opts);
                    return back.Age + "|" + back.Name;
                }
            }
        }
        """;

    string result = this.BuildAndRun(ProjectASource, projectB, LanguageVersion.CSharp7_3);
    Assert.Equal("42|Ann", result);
}

