[Fact]
public void AC4_KeySettingsMatchSameProjectOutput()
{
    // Keys are described via the chosen mechanism (a surrogate type with [Key] attributes, kept in Project B),
    // then compared byte-for-byte with an identically-shaped [MessagePackObject] declared in Project B.
    string projectB = """
        using MessagePack;
        using MessagePack.Formatters;
        using MessagePack.Resolvers;

        namespace ProjectB
        {
            public class MyTypeContract
            {
                [Key(1)] public int Age { get; set; }
                [Key(0)] public string Name { get; set; }
            }

            [GeneratedMessagePackFormatter(SurrogateType = typeof(MyTypeContract))]
            public partial class MyTypeFormatter : IMessagePackFormatter<ProjectA.MyType> { }

            [MessagePackObject]
            public class LocalType
            {
                [Key(1)] public int Age { get; set; }
                [Key(0)] public string Name { get; set; }
            }

            public static class Probe
            {
                public static string Run()
                {
                    var opts = MessagePackSerializerOptions.Standard.WithResolver(
                        CompositeResolver.Create(new IMessagePackFormatter[] { new MyTypeFormatter() }, new IFormatterResolver[] { StandardResolver.Instance }));
                    var external = MessagePackSerializer.Serialize(new ProjectA.MyType { Age = 5, Name = "Zed" }, opts);
                    var local = MessagePackSerializer.Serialize(new LocalType { Age = 5, Name = "Zed" }, MessagePackSerializerOptions.Standard);
                    var back = MessagePackSerializer.Deserialize<ProjectA.MyType>(local, opts);
                    return MessagePackSerializer.ConvertToJson(external) + "|" + MessagePackSerializer.ConvertToJson(local) + "|" + back.Age + "|" + back.Name;
                }
            }
        }
        """;

    string result = this.BuildAndRun(ProjectASource, projectB, LanguageVersion.CSharp7_3);
    string[] parts = result.Split('|');
    Assert.Equal("[\"Zed\",5]", parts[1]);
    Assert.Equal(parts[1], parts[0]);
    Assert.Equal("5", parts[2]);
    Assert.Equal("Zed", parts[3]);
}

