[Fact]
public void AC6_MisuseProducesMessagePackDiagnostics()
{
    string nonPartial = """
        using MessagePack;
        using MessagePack.Formatters;

        namespace ProjectB
        {
            [GeneratedMessagePackFormatter]
            public class NotPartialFormatter : IMessagePackFormatter<ProjectA.MyType>
            {
                public void Serialize(ref MessagePackWriter writer, ProjectA.MyType value, MessagePackSerializerOptions options) { }
                public ProjectA.MyType Deserialize(ref MessagePackReader reader, MessagePackSerializerOptions options) => null;
            }
        }
        """;
    string notFormatter = """
        using MessagePack;

        namespace ProjectB
        {
            [GeneratedMessagePackFormatter]
            public partial class NotAFormatter { }
        }
        """;

    foreach ((string src, string typeName) in new[] { (nonPartial, "NotPartialFormatter"), (notFormatter, "NotAFormatter") })
    {
        MetadataReference a = CompileProjectA(ProjectASource);
        (Compilation output, ImmutableArray<Diagnostic> genDiags) = RunGenerator(src, a, LanguageVersion.CSharp7_3);
        ImmutableArray<Diagnostic> analyzerDiags = GetAnalyzerDiagnostics(output);
        var all = genDiags.Concat(analyzerDiags).Concat(output.GetDiagnostics()).ToList();
        foreach (Diagnostic d in all)
        {
            this.logger.WriteLine($"{typeName}: {d}");
        }

        Assert.Contains(all, d => d.Id.StartsWith("MsgPack", StringComparison.Ordinal) && d.Severity == DiagnosticSeverity.Error);

        // Must not emit broken code that fails to compile with C# compiler errors.
        Assert.DoesNotContain(output.GetDiagnostics(), d => d.Severity == DiagnosticSeverity.Error && d.Id.StartsWith("CS", StringComparison.Ordinal) && d.Location.SourceTree?.FilePath.Contains(".g.cs") == true);
    }
}

