using System.IO;
using System.Linq;
using MessagePack.SourceGenerator;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;

public class CountersignFinding1
{
    private readonly ITestOutputHelper output;

    public CountersignFinding1(ITestOutputHelper output) => this.output = output;

    [Fact]
    public async Task FormattedTypeAttributesAreHonoured()
    {
        ImmutableArray<MetadataReference> baseRefs = await ReferencesHelper.DefaultTargetFrameworkReferences.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        List<MetadataReference> refs = baseRefs.Concat(ReferencesHelper.GetReferences(ReferencesSet.MessagePackAnnotations | ReferencesSet.MessagePack)).ToList();

        // Project A
        string libSource = """
            using System.Runtime.Serialization;
            namespace Lib
            {
                public class MyType
                {
                    [DataMember(Name = "id")]
                    public int Id { get; set; }

                    [IgnoreDataMember]
                    public string Secret { get; set; }
                }
            }
            """;
        CSharpCompilation lib = CSharpCompilation.Create(
            "LibA",
            new[] { CSharpSyntaxTree.ParseText(libSource) },
            refs,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        using MemoryStream ms = new();
        var emit = lib.Emit(ms);
        Assert.True(emit.Success, string.Join("\n", emit.Diagnostics));
        MetadataReference libRef = MetadataReference.CreateFromImage(ms.ToArray());

        // Project B
        string appSource = """
            using MessagePack;
            using MessagePack.Formatters;
            using Lib;

            [GeneratedMessagePackFormatter]
            public partial class F : IMessagePackFormatter<MyType> { }
            """;
        CSharpCompilation app = CSharpCompilation.Create(
            "AppB",
            new[] { CSharpSyntaxTree.ParseText(appSource) },
            refs.Append(libRef),
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new MessagePackGenerator());
        driver = driver.RunGeneratorsAndUpdateCompilation(app, out Compilation outComp, out ImmutableArray<Diagnostic> diags);
        GeneratorDriverRunResult result = driver.GetRunResult();
        string generated = string.Join("\n----\n", result.GeneratedTrees.Select(t => t.FilePath + "\n" + t.GetText().ToString()));
        this.output.WriteLine(generated);

        string formatterSource = string.Join("\n", result.GeneratedTrees.Select(t => t.GetText().ToString()).Where(s => s.Contains("partial class F")));
        Assert.False(string.IsNullOrEmpty(formatterSource), "No formatter generated:\n" + generated);

        // Expected: ignored member is not serialized; declared name "id" used.
        Assert.DoesNotContain("Secret", formatterSource);
        Assert.Contains("\"id\"", formatterSource);
    }
}

