using MessagePack.SourceGenerator;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;

public class CountersignFinding2
{
    private readonly ITestOutputHelper logger;

    public CountersignFinding2(ITestOutputHelper logger)
    {
        this.logger = logger;
    }

    [Fact]
    public async Task SurrogateIntKeyFormatterHonorsUseMapMode()
    {
        string source = """
            using MessagePack;
            using MessagePack.Formatters;

            namespace N
            {
                [GeneratedMessagePackResolver(UseMapMode = true)]
                partial class MyResolver { }

                public class External
                {
                    public int A { get; set; }
                    public string B { get; set; }
                }

                public class Surrogate
                {
                    [Key(0)] public int A { get; set; }
                    [Key(1)] public string B { get; set; }
                }

                [GeneratedMessagePackFormatter(SurrogateType = typeof(Surrogate))]
                public partial class ExternalFormatter : IMessagePackFormatter<External> { }

                [MessagePackObject]
                public class InProject
                {
                    [Key(0)] public int A { get; set; }
                    [Key(1)] public string B { get; set; }
                }
            }
            """;

        var refs = (await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None)).ToList();
        refs.AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));
        var compilation = CSharpCompilation.Create(
            "TestAsm",
            new[] { CSharpSyntaxTree.ParseText(source, new CSharpParseOptions(LanguageVersion.Latest)) },
            refs,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new MessagePackGenerator());
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out _, out var diags);
        var result = driver.GetRunResult();
        foreach (var d in diags.Concat(result.Diagnostics))
        {
            this.logger.WriteLine(d.ToString());
        }

        string? externalCode = null;
        string? inProjectCode = null;
        foreach (var tree in result.GeneratedTrees)
        {
            string text = tree.GetText().ToString();
            this.logger.WriteLine("==== " + tree.FilePath);
            this.logger.WriteLine(text);
            if (text.Contains("partial class ExternalFormatter"))
            {
                externalCode = text;
            }

            if (text.Contains("InProjectFormatter"))
            {
                inProjectCode = text;
            }
        }

        Assert.NotNull(inProjectCode);
        Assert.NotNull(externalCode);

        // Sanity: in-project [MessagePackObject] with int keys is written as a map under UseMapMode.
        Assert.Contains("WriteMapHeader", inProjectCode);

        // Expected: the surrogate-keyed generated formatter is also written as a map.
        Assert.DoesNotContain("WriteArrayHeader", externalCode);
        Assert.Contains("WriteMapHeader", externalCode);
    }
}

