using MessagePack;
using MessagePack.SourceGenerator;
using MessagePack.SourceGenerator.Tests;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;

public class CountersignFinding5
{
    private readonly ITestOutputHelper output;

    public CountersignFinding5(ITestOutputHelper output) => this.output = output;

    [Fact]
    public async Task GeneratedFormatterForMessagePackObjectTypeIsNotSilentlyDropped()
    {
        string source = """
            using MessagePack;
            using MessagePack.Formatters;

            [MessagePackObject]
            public class T
            {
                [Key(0)]
                public int X { get; set; }
            }

            [GeneratedMessagePackFormatter]
            public partial class TF : IMessagePackFormatter<T>
            {
            }
            """;

        var refs = (await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, default))
            .Concat(new[]
            {
                MetadataReference.CreateFromFile(typeof(MessagePackObjectAttribute).Assembly.Location),
                MetadataReference.CreateFromFile(typeof(MessagePackSerializer).Assembly.Location),
            });

        var compilation = CSharpCompilation.Create(
            "TestAsm",
            new[] { CSharpSyntaxTree.ParseText(source, new CSharpParseOptions(LanguageVersion.Preview)) },
            refs,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary, nullableContextOptions: NullableContextOptions.Enable));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new MessagePackGenerator()).WithUpdatedParseOptions(new CSharpParseOptions(LanguageVersion.Preview));
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation outCompilation, out ImmutableArray<Diagnostic> genDiags);

        foreach (var tree in outCompilation.SyntaxTrees)
        {
            this.output.WriteLine("=== " + tree.FilePath);
            this.output.WriteLine(tree.ToString());
        }

        var compileErrors = outCompilation.GetDiagnostics().Where(d => d.Severity == DiagnosticSeverity.Error).ToList();
        foreach (var d in genDiags.Concat(compileErrors))
        {
            this.output.WriteLine(d.ToString());
        }

        bool tfHasNoBody = compileErrors.Any(d => d.Id == "CS0535");
        bool generatorExplained = genDiags.Any(d => d.Id.StartsWith("MsgPack", StringComparison.Ordinal));

        // Correct behaviour: either TF gets a generated body, or the generator explains why it did not.
        Assert.True(
            !tfHasNoBody || generatorExplained,
            "TF has no Serialize/Deserialize (CS0535) and generator reported no MsgPack diagnostic. Errors: " + string.Join(" | ", compileErrors.Select(e => e.ToString())));
    }
}
